from pathlib import Path
import json
root=Path('/mnt/data/sorbent_work')
def edit(path, pairs):
 p=root/path; s=p.read_text()
 for old,new in pairs:
  if old not in s:
   print('NOT FOUND',path,old[:90].replace('\n',' '))
  else: s=s.replace(old,new)
 p.write_text(s)

